class BowlingGame:
    def __init__(self):
        self._frames = []
        self._current_frame = []

    def roll(self, pins):
        if not 0 <= pins <= 10:
            raise Exception("A roll cannot score negative points or more than 10 points")

        if len(self._frames) == 10:
            raise Exception("Cannot roll if the game already has ten frames")

        if len(self._frames) == 9:
            self._roll_tenth_frame(pins)
        else:
            self._roll_normal_frame(pins)

    def _roll_normal_frame(self, pins):
        if len(self._current_frame) == 0:
            self._current_frame.append(pins)
            if pins == 10:
                self._frames.append(self._current_frame)
                self._current_frame = []
        else:
            if pins > 10 - self._current_frame[0]:
                raise Exception("Two rolls in a frame cannot score more than 10 points")
            self._current_frame.append(pins)
            self._frames.append(self._current_frame)
            self._current_frame = []

    def _roll_tenth_frame(self, pins):
        rolls = self._current_frame
        if len(rolls) == 2:
            if rolls[0] != 10 and sum(rolls) < 10:
                raise Exception("Cannot roll after an open frame in the tenth frame")
            if rolls[0] == 10 and rolls[1] != 10 and pins > 10 - rolls[1]:
                raise Exception("Two rolls in a frame cannot score more than 10 points")
        self._current_frame.append(pins)
        if self._tenth_frame_complete():
            self._frames.append(self._current_frame)
            self._current_frame = []

    def _tenth_frame_complete(self):
        rolls = self._current_frame
        if len(rolls) == 3:
            return True
        if len(rolls) == 2:
            return rolls[0] != 10 and sum(rolls) == 10
        return False

    def score(self):
        if len(self._frames) != 10:
            raise Exception("Cannot score an incomplete game")

        rolls = [pin for frame in self._frames for pin in frame]
        total = 0
        for i, frame in enumerate(self._frames):
            if frame[0] == 10:
                total += 10 + rolls[i + 1] + rolls[i + 2]
            elif sum(frame) == 10:
                total += 10 + rolls[i + 2]
            else:
                total += sum(frame)
        return total

